/**
 * Demo content for Kithul & Co., a fictional restaurant.
 *
 * Single source of truth for:
 *   - `supabase/seed.sql`, generated by `npm run db:seed` (scripts/build-seed-sql.ts)
 *   - the app's no-database fallback (docs/DECISIONS.md D9), so the site works
 *     before Supabase is configured
 *
 * Rows use the database column names. IDs are derived from slugs so they are
 * identical in every environment.
 *
 * This file must stay runnable by plain Node (type stripping): no path aliases,
 * no enums, and no imports other than `node:` built-ins.
 *
 * Sinhala and Tamil names are drafts and need review by a native speaker.
 */
import { createHash } from "node:crypto";

// ---------------------------------------------------------------------------
// Helpers
// ---------------------------------------------------------------------------

export type I18nText = { en: string; si?: string; ta?: string };

/** A UUID derived from a kind and key, so seeds are reproducible. */
export function stableId(kind: string, key: string): string {
  const hex = createHash("sha256").update(`kithul-demo:${kind}:${key}`).digest("hex");
  const variant = ((parseInt(hex[16] ?? "0", 16) & 0x3) | 0x8).toString(16);
  return [
    hex.slice(0, 8),
    hex.slice(8, 12),
    `8${hex.slice(13, 16)}`,
    `${variant}${hex.slice(17, 20)}`,
    hex.slice(20, 32),
  ].join("-");
}

/** Remote photos (credits in docs/CREDITS.md). Served through next/image. */
const unsplash = (id: string) =>
  `https://images.unsplash.com/${id}?auto=format&fit=crop&w=1600&q=80`;
const pexels = (id: string) =>
  `https://images.pexels.com/photos/${id}/pexels-photo-${id}.jpeg?auto=compress&cs=tinysrgb&w=1600`;

/** Rupees to cents. */
const rs = (rupees: number) => Math.round(rupees * 100);

const t = (en: string, si?: string, ta?: string): I18nText => ({
  en,
  ...(si ? { si } : {}),
  ...(ta ? { ta } : {}),
});

// ---------------------------------------------------------------------------
// Row types (database column names)
// ---------------------------------------------------------------------------

export type DayKey = "mon" | "tue" | "wed" | "thu" | "fri" | "sat" | "sun";
export type OpeningHours = Record<DayKey, [string, string][]>;

export type DeliveryFeeRules = {
  baseFeeCents: number;
  includedKm: number;
  perKmCents: number;
  freeAboveCents: number | null;
};

export type BranchRow = {
  id: string;
  slug: string;
  name_i18n: I18nText;
  address_line: string;
  city: string;
  district: string;
  lat: number;
  lng: number;
  phone: string;
  whatsapp: string | null;
  email: string | null;
  delivery_radius_km: number;
  delivery_fee_rules: DeliveryFeeRules;
  opening_hours: OpeningHours;
  seating_capacity: number;
  image_path: string | null;
  is_accepting_orders: boolean;
  is_active: boolean;
  sort_order: number;
};

export type CategoryRow = {
  id: string;
  slug: string;
  name_i18n: I18nText;
  description_i18n: Partial<I18nText>;
  sort_order: number;
  is_active: boolean;
};

export type DietaryTag = "vegetarian" | "vegan" | "halal" | "contains-nuts";

export type MenuItemRow = {
  id: string;
  category_id: string;
  slug: string;
  name_i18n: I18nText;
  description_i18n: Partial<I18nText>;
  base_price_cents: number;
  image_path: string | null;
  dietary_tags: DietaryTag[];
  spice_selectable: boolean;
  is_alcohol: boolean;
  is_signature: boolean;
  is_active: boolean;
  sort_order: number;
};

export type ItemOptionRow = {
  id: string;
  menu_item_id: string;
  name_i18n: I18nText;
  selection: "single" | "multiple";
  is_required: boolean;
  max_select: number | null;
  sort_order: number;
};

export type ItemOptionValueRow = {
  id: string;
  option_id: string;
  name_i18n: I18nText;
  price_delta_cents: number;
  is_default: boolean;
  is_active: boolean;
  sort_order: number;
};

export type BranchMenuOverrideRow = {
  branch_id: string;
  menu_item_id: string;
  price_cents: number | null;
  is_available: boolean;
};

export type PromotionRow = {
  id: string;
  slug: string;
  title_i18n: I18nText;
  body_i18n: Partial<I18nText>;
  image_path: string | null;
  cta_label_i18n: I18nText | null;
  cta_href: string | null;
  starts_on: string | null;
  ends_on: string | null;
  is_active: boolean;
  sort_order: number;
};

export type HolidayRow = {
  id: string;
  date: string;
  kind: "poya" | "public" | "festival";
  name_i18n: I18nText;
  is_alcohol_free: boolean;
};

export type ReviewRow = {
  id: string;
  branch_id: string | null;
  author_name: string;
  rating: number;
  body: string;
  status: "pending" | "approved" | "rejected";
  created_at: string;
};

