export const menuItems: MenuItemRow[] = [];
export const itemOptions: ItemOptionRow[] = [];
export const itemOptionValues: ItemOptionValueRow[] = [];

for (const [categorySlug, specs] of Object.entries(MENU)) {
  specs.forEach((spec, index) => {
    const id = stableId("menu-item", spec.slug);
    menuItems.push({
      id,
      category_id: categoryId(categorySlug),
      slug: spec.slug,
      name_i18n: spec.name,
      description_i18n: { en: spec.description },
      base_price_cents: rs(spec.price),
      image_path: spec.image ?? null,
      dietary_tags: spec.tags ?? [],
      spice_selectable: spec.spicy ?? false,
      is_alcohol: spec.alcohol ?? false,
      is_signature: spec.signature ?? false,
      is_active: true,
      sort_order: index + 1,
    });

    (spec.options ?? []).forEach((option, optionIndex) => {
      const optionId = stableId("item-option", `${spec.slug}/${option.key}`);
      itemOptions.push({
        id: optionId,
        menu_item_id: id,
        name_i18n: option.name,
        selection: option.selection,
        is_required: option.required,
        max_select: option.maxSelect ?? null,
        sort_order: optionIndex + 1,
      });
      option.values.forEach((value, valueIndex) => {
        itemOptionValues.push({
          id: stableId("item-option-value", `${spec.slug}/${option.key}/${value.key}`),
          option_id: optionId,
          name_i18n: value.name,
          price_delta_cents: value.delta,
          is_default: value.isDefault ?? false,
          is_active: true,
          sort_order: valueIndex + 1,
        });
      });
    });
  });
}

const itemId = (slug: string) => stableId("menu-item", slug);

